-- classic-17-the-fall-of-the-house-of-usher: "The Fall of the House of Usher" by clasice
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9300-001700000000'::uuid, '00000000-0000-4000-8000-000000000100'::uuid, 'the-fall-of-the-house-of-usher-classic',
  $demo$The Fall of the House of Usher$demo$, $demo$A man visits his childhood friend Roderick Usher in a crumbling house by a dark lake. The friend is ill, his sister is dying, and the house itself seems to be listening.

Source edition: 1839.$demo$, 'en',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '90 days', now() - interval '90 days', now() - interval '92 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9300-001700000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9300-001700000000'::uuid, '00000000-0000-4000-8000-000000000100'::uuid, array['domeniu public', 'classic', 'gothic', 'horror']);
insert into public.classic_authors (name, died_year) values ($demo$Edgar Allan Poe$demo$, 1849)
